<script setup lang="ts">import{reactive,ref}from"vue";import{feedbackApi}from"../../api/feedback";const saved=ref(false);const form=reactive({task_completion_rate:1,useful:null as boolean|null,citation_correct:null as boolean|null,data_correct:null as boolean|null,error_type:"none",comment:"",next_step:""});async function submit(){await feedbackApi.create(form);saved.value=true}</script>
<template><main class="feedback"><p>IMPROVE WITH EVIDENCE</p><h1>匿名试用反馈</h1><p>不填写姓名、邮箱或论文正文。请给出具体观察，帮助区分阻塞、严重和一般问题。</p><form @submit.prevent="submit"><label>任务完成率 <input v-model.number="form.task_completion_rate" type="number" min="0" max="1" step="0.1" required/></label><fieldset><legend>有帮助吗？</legend><label><input v-model="form.useful" type="radio" :value="true"/>是</label><label><input v-model="form.useful" type="radio" :value="false"/>否</label></fieldset><fieldset><legend>引用支持回答吗？</legend><label><input v-model="form.citation_correct" type="radio" :value="true"/>是</label><label><input v-model="form.citation_correct" type="radio" :value="false"/>否</label></fieldset><fieldset><legend>关键数据正确吗？</legend><label><input v-model="form.data_correct" type="radio" :value="true"/>是</label><label><input v-model="form.data_correct" type="radio" :value="false"/>否</label></fieldset><label>错误严重度 <select v-model="form.error_type"><option value="none">无</option><option value="blocker">阻塞</option><option value="severe">严重</option><option value="general">一般</option></select></label><label>哪一处错误？ <textarea v-model="form.comment" maxlength="2000"/></label><label>下一步最想做什么？ <textarea v-model="form.next_step" maxlength="1000"/></label><button>提交匿名反馈</button></form><p v-if="saved">反馈已保存在本机。</p><a :href="feedbackApi.exportUrl">导出匿名反馈 CSV</a></main></template>
<style scoped>.feedback{max-width:760px;margin:auto;padding:5rem 1rem}.feedback h1{font:700 4rem Georgia,serif;color:#173f3c}form{display:grid;gap:.9rem;padding:1.2rem;background:white;border-radius:16px}label{display:grid;gap:.3rem}fieldset label{display:inline-flex;margin-right:1rem}input,select,textarea,button{padding:.7rem;border:1px solid #9cafaa;border-radius:8px}textarea{min-height:70px}button{background:#173f3c;color:white;font-weight:700}</style>
